// ══════════════════════════════════════════
// NODO: Procesar datos + calcular precio
// ══════════════════════════════════════════
const body = $input.first().json.body || $input.first().json;

// Extraer campos
const nombre    = (body.nombre    || '').trim();
const telefono  = (body.telefono  || '').trim().replace(/[^0-9]/g, '');
const direccion = (body.direccion || '').trim();
const vehiculo  = (body.vehiculo  || '').trim();
const servicio  = (body.servicio  || '').trim();
const fecha     = (body.fecha     || '').trim();
const hora      = (body.hora      || 'Por confirmar').trim();

// Tabla de precios
const precios = {
  basico:    { auto: 5000,  suv: 7000  },
  encerado:  { auto: 7000,  suv: 10000 },
  detallado: { auto: 25000, suv: 25000 }
};

// Nombres legibles
const nombreServicio = {
  basico:    'Lavado básico + aspirado',
  encerado:  'Lavado + aspirado + encerado',
  detallado: 'Detallado completo'
};
const nombreVehiculo = {
  auto: 'Automóvil 4x2',
  suv:  'SUV / 4x4'
};

// Calcular precio
const precio = (precios[servicio] && precios[servicio][vehiculo])
  ? precios[servicio][vehiculo]
  : 0;

// Formatear fecha
let fechaFormato = fecha;
try {
  const d = new Date(fecha + 'T12:00:00');
  fechaFormato = d.toLocaleDateString('es-CR', {
    weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'
  });
} catch(e) { fechaFormato = fecha; }

// Número de WhatsApp completo con código de Costa Rica
const telefonoCR = telefono ? '506' + telefono : '50687375227';

// Validación
const valido = !!(nombre && direccion && vehiculo && servicio && fecha && telefono && precio > 0);

return [{
  json: {
    // Datos originales
    nombre, telefono, telefonoCR, direccion,
    vehiculo: nombreVehiculo[vehiculo] || vehiculo,
    vehiculoRaw: vehiculo,
    servicio: nombreServicio[servicio] || servicio,
    servicioRaw: servicio,
    fecha, fechaFormato, hora,
    // Precio
    precio,
    precioFormato: '\u20a1' + precio.toLocaleString('es-CR'),
    // Metadatos
    timestamp: new Date().toISOString(),
    fechaHoraLegible: new Date().toLocaleString('es-CR', { timeZone: 'America/Costa_Rica' }),
    valido,
    errorMsg: !valido ? 'Faltan campos obligatorios o precio no calculado.' : null
  }
}];

