// Filtrar solo las reservas de HOY
const hoy = new Date().toISOString().split('T')[0];
const reservasHoy = $input.all().filter(item => {
  return item.json.Fecha_Servicio === hoy;
});

if (reservasHoy.length === 0) {
  return [{ json: { hayReservas: false, cantidad: 0 } }];
}

return reservasHoy.map(r => ({
  json: {
    hayReservas: true,
    nombre: r.json.Nombre,
    telefono: r.json.Telefono,
    telefonoCR: '506' + r.json.Telefono.replace(/[^0-9]/g,''),
    direccion: r.json.Direccion,
    servicio: r.json.Servicio,
    hora: r.json.Hora_Preferida,
    precio: r.json.Precio
  }
}));

